{"explanation":"At height z above the base, the cone’s radius is R(1 − z/h), so its horizontal slice has area πR²(1 − z/h)². The cylinder’s slices all have area πR². Adding the slices over the full height gives the cone a volume of πR²h/3—exactly one third of the cylinder’s. Move the slider to compare their cross-sections.","manimCode":"const title = new Text({ text: 'Same base. Same height. Why one third?', fontSize: 28, color: WHITE });
title.moveTo([-0.8, 3.15, 0]);
await scene.play(new Write(title));

const baseY = -1.25;
const h = 3;
const radius = 1;
const cylinderX = -3.1;
const coneX = 0.3;

function ellipseVertices(cx, cy, rx, ry) {
  const pts = [];
  for (let i = 0; i < 64; i++) {
    const a = 2 * Math.PI * i / 64;
    pts.push([cx + rx * Math.cos(a), cy + ry * Math.sin(a), 0]);
  }
  return pts;
}
function ellipse(cx, cy, rx, ry, color, opacity) {
  const obj = new Polygon({ vertices: ellipseVertices(cx, cy, rx, ry), color });
  obj.setFill(color, opacity);
  obj.setStrokeWidth(2);
  return obj;
}

const cylinderBody = new Polygon({ vertices: [
  [cylinderX-radius, baseY, 0], [cylinderX+radius, baseY, 0],
  [cylinderX+radius, baseY+h, 0], [cylinderX-radius, baseY+h, 0]
], color: BLUE });
cylinderBody.setFill(BLUE, 0.16);
const cylinderBase = ellipse(cylinderX, baseY, radius, 0.22, BLUE, 0.2);
const cylinderTop = ellipse(cylinderX, baseY+h, radius, 0.22, BLUE, 0.14);
const coneBody = new Polygon({ vertices: [
  [coneX-radius, baseY, 0], [coneX+radius, baseY, 0], [coneX, baseY+h, 0]
], color: ORANGE });
coneBody.setFill(ORANGE, 0.18);
const coneBase = ellipse(coneX, baseY, radius, 0.22, ORANGE, 0.22);

const cylinderLabel = new Text({ text: 'Cylinder', fontSize: 25, color: BLUE });
cylinderLabel.moveTo([cylinderX, 2.3, 0]);
const coneLabel = new Text({ text: 'Cone', fontSize: 25, color: ORANGE });
coneLabel.moveTo([coneX, 2.3, 0]);
await scene.play(new AnimationGroup([
  new FadeIn(cylinderBody), new FadeIn(cylinderBase), new FadeIn(cylinderTop),
  new FadeIn(coneBody), new FadeIn(coneBase), new Write(cylinderLabel), new Write(coneLabel)
]));

let fraction = 0.5;
const cylinderSlice = ellipse(cylinderX, baseY + h*fraction, radius, 0.22, YELLOW, 0.65);
const coneSlice = ellipse(coneX, baseY + h*fraction, radius*(1-fraction), 0.22*(1-fraction), YELLOW, 0.65);
const levelGuide = new Polygon({ vertices: [
  [cylinderX-radius, baseY+h*fraction, 0], [coneX+radius, baseY+h*fraction, 0]
], color: GRAY });
levelGuide.setFillOpacity(0);
levelGuide.setStrokeWidth(1);
scene.add(levelGuide, cylinderSlice, coneSlice);
let heightLabel;
let ratioLabel;
function refreshSlices(v) {
  fraction = v;
  const yy = baseY + h*v;
  const rr = radius*(1-v);
  cylinderSlice.setVertices(ellipseVertices(cylinderX, yy, radius, 0.22));
  coneSlice.setVertices(ellipseVertices(coneX, yy, Math.max(rr, 0.001), Math.max(0.22*(1-v), 0.001)));
  levelGuide.setVertices([[cylinderX-radius, yy, 0], [coneX+radius, yy, 0]]);
  if (heightLabel) scene.remove(heightLabel);
  if (ratioLabel) scene.remove(ratioLabel);
  heightLabel = new Text({ text: 'Height: ' + v.toFixed(2) + ' h', fontSize: 23, color: WHITE });
  heightLabel.moveTo([3.75, 0.25, 0]);
  ratioLabel = new Text({ text: 'Slice area: ' + (100*(1-v)*(1-v)).toFixed(1) + '%', fontSize: 23, color: YELLOW });
  ratioLabel.moveTo([3.75, -0.3, 0]);
  scene.add(heightLabel, ratioLabel);
}
refreshSlices(fraction);
const comparisonNote = new Text({ text: 'of the cylinder slice', fontSize: 20, color: GRAY });
comparisonNote.moveTo([3.75, -0.75, 0]);
scene.add(comparisonNote);

const sliceFormula = new MathTex({ latex: 'A_{\\mathrm{cone}}(z)=\\pi R^2\\left(1-\\frac{z}{h}\\right)^2' });
await sliceFormula.waitForRender();
sliceFormula.scale(0.76);
sliceFormula.moveTo([-0.5, -2.15, 0]);
await scene.play(new Write(sliceFormula));
const volumeFormula = new MathTex({ latex: 'V_{\\mathrm{cone}}=\\int_0^h A_{\\mathrm{cone}}(z)\\,dz=\\frac{1}{3}\\pi R^2h=\\frac{1}{3}V_{\\mathrm{cylinder}}' });
await volumeFormula.waitForRender();
volumeFormula.scale(0.73);
volumeFormula.moveTo([0, -3.05, 0]);
await scene.play(new Write(volumeFormula));

for (const v of [0.25, 0.5, 0.75, 0.5]) {
  refreshSlices(v);
  await scene.wait(0.8);
}
const controls = new Controls(scene, { position: 'top-right', width: 240 });
controls.addSlider({ label: 'Slice height z / h', min: 0, max: 1, value: 0.5, step: 0.01, onChange: refreshSlices });
makeHoverable(coneSlice, scene, { hoverColor: WHITE, hoverScale: 1 });
makeHoverable(cylinderSlice, scene, { hoverColor: WHITE, hoverScale: 1 });
await scene.wait(999999);"}

